const resume = $input.item.binary?.data;
const resumeUrl = $input.item.json.resume_url;
const jobDescriptions = $input.item.json.job_descriptions || [];

if (!resume && !resumeUrl) {
  throw new Error('No resume file or URL provided');
}

return {
  json: {
    parsing_id: `resume_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    timestamp: new Date().toISOString(),
    job_descriptions: jobDescriptions,
    analysis_types: ['skills', 'experience', 'education', 'certifications', 'job_matching']
  },
  binary: resume ? { data: resume } : undefined
};

