const parsedResume = JSON.parse($input.item.json.choices[0].message.content);
const skills = parsedResume.skills || [];

// Categorize skills
const technicalSkills = skills.filter(s => ['programming', 'technical', 'software'].includes(s.category?.toLowerCase()));
const softSkills = skills.filter(s => ['soft', 'communication', 'leadership'].includes(s.category?.toLowerCase()));

// Calculate experience metrics
const workExperience = parsedResume.work_experience || [];
const totalYearsExperience = workExperience.reduce((total, job) => {
  const duration = job.duration || '';
  const years = duration.match(/(\d+)\s*y/i)?.[1] || 0;
  const months = duration.match(/(\d+)\s*m/i)?.[1] || 0;
  return total + parseInt(years) + parseInt(months) / 12;
}, 0);

// Extract seniority level
const recentPosition = workExperience[0]?.position?.toLowerCase() || '';
let seniorityLevel = 'entry';
if (recentPosition.includes('senior') || recentPosition.includes('lead') || totalYearsExperience >= 7) {
  seniorityLevel = 'senior';
} else if (recentPosition.includes('mid') || totalYearsExperience >= 3) {
  seniorityLevel = 'mid';
}

return {
  json: {
    ...parsedResume,
    derived_metrics: {
      total_years_experience: parseFloat(totalYearsExperience.toFixed(1)),
      seniority_level: seniorityLevel,
      technical_skills_count: technicalSkills.length,
      soft_skills_count: softSkills.length,
      education_level: parsedResume.education?.[0]?.degree || 'Not specified',
      certifications_count: (parsedResume.certifications || []).length
    },
    parsing_id: $('Validate Resume Input').item.json.parsing_id
  }
};

