parameters.functionCode:
const items = $input.all();
const resumeData = items.find(item => item.json.personal_info)?.json;
const matchingResult = items.find(item => item.json.choices);
const jobMatches = matchingResult ? JSON.parse(matchingResult.json.choices[0].message.content) : {};

// Sort job matches by score
const rankedJobs = (jobMatches.job_matches || []).sort((a, b) => b.match_score - a.match_score);

// Generate candidate summary
const candidateSummary = {
  name: resumeData?.personal_info?.name,
  email: resumeData?.personal_info?.email,
  location: resumeData?.personal_info?.location,
  years_experience: resumeData?.derived_metrics?.total_years_experience,
  seniority_level: resumeData?.derived_metrics?.seniority_level,
  education: resumeData?.derived_metrics?.education_level,
  top_skills: (resumeData?.skills || []).slice(0, 10).map(s => s.skill),
  certifications: resumeData?.certifications || []
};

// Calculate overall employability score
const employabilityScore = Math.round(
  (resumeData?.derived_metrics?.total_years_experience * 10) +
  (resumeData?.derived_metrics?.technical_skills_count * 2) +
  (resumeData?.derived_metrics?.certifications_count * 5) +
  (['master', 'phd'].some(d => resumeData?.derived_metrics?.education_level?.toLowerCase().includes(d)) ? 15 : 0) +
  (['bachelor', 'bs', 'ba'].some(d => resumeData?.derived_metrics?.education_level?.toLowerCase().includes(d)) ? 10 : 0)
);

const result = {
  parsing_id: resumeData?.parsing_id,
  timestamp: new Date().toISOString(),
  candidate_summary: candidateSummary,
  employability_score: Math.min(employabilityScore, 100),
  full_resume_data: resumeData,
  job_matching: {
    jobs_analyzed: rankedJobs.length,
    best_match: rankedJobs[0] || null,
    all_matches: rankedJobs,
    average_match_score: rankedJobs.length > 0 ? 
      Math.round(rankedJobs.reduce((sum, j) => sum + j.match_score, 0) / rankedJobs.length) : 0,
    strong_fits_count: rankedJobs.filter(j => j.match_score >= 80).length,
    good_fits_count: rankedJobs.filter(j => j.match_score >= 60 && j.match_score < 80).length
  },
  recommendations: {
    skill_gaps: rankedJobs[0]?.missing_skills || [],
    career_advice: jobMatches.career_advice || [],
    next_steps: [
      rankedJobs[0]?.match_score >= 80 ? 'Apply immediately to top matches' : 'Consider upskilling before applying',
      'Focus on highlighting: ' + (rankedJobs[0]?.strengths || []).slice(0, 3).join(', '),
      'Address concerns: ' + (rankedJobs[0]?.concerns || []).slice(0, 2).join(', ')
    ]
  },
  metadata: {
    parsing_method: 'gpt4_vision',
    matching_model: 'gpt4_turbo',
    processing_time_ms: Date.now() - new Date(resumeData?.timestamp || Date.now()).getTime()
  }
};

return { json: result };
